def SET(cid,mid,c,l,h,f=None,**kw):
    m=M(cid,mid); k=m['claude']; k.update(central=c,low=l,high=h)
    if f: k['formula']=f
    for a,v in kw.items():
        if a in ('verdict','obstacle','proposal','claimed','a_confirmer','title'): m[a]=v
        else: k[a]=v
