# (Montaigne 2022 remis aux salaires 2024) ; « 65 ans » : aucun effet en 2030 au rythme actuel (Cour des comptes 2025), seule compte la fin
# de la suspension (+1,8, comme Zemmour) ; aides réservées : part des étrangers 2023 (Insee)
AMEF="Méthode Montaigne 2024 sur les dépenses réelles 2025 : AME de droit commun 1 351 M€ − 50 % × part hospitalière 60,8 % (2024) × 1 351 = 1 351 × 0,696 ≈ +0,94 → +0,9 Md€ (avec la part hospitalière de Montaigne, 70 % : +0,88) ; borne basse : valeur 2024 (0,7) ; borne haute : toute l'AME de droit commun 2025 (1,35), soins urgents maintenus"
AMEIN=[{'label': 'AME de droit commun 2025, dépense réelle', 'value': "1 351 M€ (dont dépassement payé par la Sécurité sociale) ; coût total de l'AME 1 470 M€", 'source': 'Sénat, rapport n° 736 (2025-2026)', 'url': 'https://www.senat.fr/rap/l25-736-228/l25-736-2281.pdf'}, {'label': 'Part des prestations hospitalières (2024)', 'value': '60,8 %', 'source': 'Sénat, rapport général n° 139 (2025-2026), annexe Santé', 'url': 'https://www.senat.fr/rap/l25-139-327/l25-139-3271.pdf'}, {'label': 'Méthode (report de 50 % des soins hospitaliers vers les soins urgents)', 'value': '1,1 Md€ − 0,4 ≈ 0,7 Md€ (base 2024)', 'source': 'Institut Montaigne (2024)', 'url': 'https://www.institutmontaigne.org/legislatives-2024/rassemblement-national/suppression-de-laide-medicale-detat-ame-et-remplacement-par-laide-durgence-vitale/'}, {'label': 'Crédits AME 2026', 'value': '1,216 Md€ (comme en 2025)', 'source': 'Sénat, rapport général n° 139 (2025-2026)', 'url': 'https://www.senat.fr/rap/l25-139-327/l25-139-3271.pdf'}]
for cid in ('le-pen','retailleau','lisnard','zemmour'):
    SET(cid,'ame',0.9,0.7,1.35,AMEF,method='ascendant',inputs=AMEIN)
M('lisnard','ame')['claude']['note']="Report vers les urgences déduit. Le chiffre du camp (0,7) est inférieur au chiffrage."
M('zemmour','ame')['claude']['note']="Chiffre du camp : 1,3 Md€ (budget2027.fr), hors médiane."
PROF39=[{'label': '+10 % pour tous les enseignants (salaires bruts 2019, 898 400 enseignants)', 'value': '3,33 Md€', 'source': 'Institut Montaigne (2022)', 'url': 'https://www.institutmontaigne.org/presidentielle-2022/legislatives-2022/ensemble/revaloriser-les-salaires-des-enseignants-de-10'}, {'label': 'Salaire net moyen des enseignants (Insee, EQTP)', 'value': '2 664 € (2019) ; 3 190 € (2024)', 'source': 'Insee Première n° 1861 ; DEPP NI 26.36 (Insee Première n° 2100)', 'url': 'https://www.insee.fr/fr/statistiques/fichier/version-html/5393253/ip1861.pdf'}, {'label': 'Enseignants à la rentrée 2024', 'value': '712 806 (public) + 139 946 (privé) ; 725 000 + 141 000 en 2019-2020', 'source': 'Sénat, rapport PLF 2026, Enseignement scolaire', 'url': 'https://www.senat.fr/rap/l25-139-313/l25-139-3137.html'}]
