for cid in ('philippe','lisnard'): SET(cid,'profs',-5.5,-7.8,-2.7,PROFF,inputs=PROF39)
SET('glucksmann','ecole',-4.2,-6.0,-2.7,"+10 % pour tous = 3,9 Md€ (valeur commune remise à 2024) ; avec la hausse graduée jusqu'à +25 %, ≈ 6 Md€ selon le candidat, soit ≈ +15 % en moyenne au barème commun (6 / 3,9 × 10) ; hausse planifiée sur 5 ans : 70 % en 2030 = −4,2 ; bornes : −6 (hausse complète dès 2030) et −2,7 (+10 % seul, 70 %)")
K('attal','profs',-1.9,-2.8,-1.8,"Chiffre du candidat : 2,5 à 3 Md€ ; 70 % en 2030 (règle commune) ≈ −1,9 ; borne haute : part explicite seule, +200 € net = +6,5 % de 3 090 € → 2,5 Md€ au barème commun (3,9 par +10 %), 70 % = −1,8 ; borne basse inchangée")
RET65='Fin de la suspension (retour au calendrier de 2023) ≈ +1,8 Md€ en 2030 ; 65 ans après les 64 ans (génération 1968, en 2032) : aucun effet en 2030 (Cour des comptes 2025 : +4,7 Md€ pour les retraites en 2035, effet à partir de 2032) ; borne haute +5,8 si le recul était accéléré (variante de la Cour : 65 ans dès la génération 1968, +8,4 Md€ en 2035)'
SET('philippe','retraites',1.8,1.8,5.8,RET65+' ; 45 annuités : ≈ 0 en 2030 (au plus un trimestre de plus pour les générations qui partent en 2030) ; capitalisation alimentée par les excédents de l\'Agirc-Arrco : 0 si le fonds reste une administration publique (classement non publié), sinon au plus ≈ −1,4',note="Les chiffres iFRAP 2023 (13,6 et 17,6 Md€ en 2030) supposaient un calendrier lancé en 2023 ; après la suspension votée en 2025, une reprise en 2027-2028 ne peut atteindre 65 ans avant 2030 qu'en accélérant le rythme, ce que le programme ne dit pas (« en moins de dix ans »). ≈ 30 Md€ vers 2035-2036 selon le camp.",proposal="Rétablir 64 ans et 43 annuités, puis 65 ans et 45 annuités en moins de dix ans ; capitalisation collective obligatoire alimentée par les excédents de l'Agirc-Arrco.")
SET('lisnard','retraites',1.8,1.8,5.8,'Fin de la suspension ≈ +1,8 Md€ en 2030 ; 65 ans après les 64 ans : effet à partir de 2032 (Cour des comptes 2025) ; borne haute +5,8 si le recul était accéléré (même règle que Philippe)',note='Calendrier du candidat non publié : même lecture que Philippe et Zemmour. Coût de transition vers la capitalisation exclu.')
SET('zemmour','aides',7.3,2.6,7.8,'Montaigne 2022 actualisé : RSA 1 465 × 12,2/11,78 (RSA 2025) = 1 517 ; aides au logement 1 894 et allocations familiales 2 216 × 8,2/7,6 (part des étrangers 2023) = 2 044 et 2 391 ; ASPA 1 184 × 1 043,59/903,20 = 1 368 → 7,3 Md€ ; borne haute avec la part provisoire 2025 (9,1 %) : 7,8 ; borne basse : variante restreinte (Montaigne 2024) 2,6',note="Reconfirmée le 17/09/2026 ; comptée « si la révision passe ». Montants totaux des aides au logement et des allocations familiales non actualisés (allocataires en baisse : 5,6 M et 4,7 M selon la Cnaf ; montants unitaires revalorisés) ; part de 2023 retenue car l'Insee signale une rupture de série en 2024. Le plan dit « aux citoyens français » (ressortissants de l'UE compris), plus large que la version chiffrée.")
M('zemmour','aides')['claude']['inputs']+=[{'label':'Part des étrangers dans la population','value':'7,6 % (2020), 8,2 % (2023), 9,1 % (2025, provisoire ; rupture de série en 2024)','source':'Insee','url':'https://insee.fr/fr/statistiques/3633212'}]
SET('lisnard','aides5',2.3,1.7,3.2,"Si la mesure passe : même condition (5 ans de séjour régulier) que la mesure chiffrée par l'Institut Montaigne en 2022 (2 127 M€ : aides au logement, allocations familiales, accueil du jeune enfant ; 40 % des allocataires étrangers) ; part des étrangers 7,6 % (2020) → 8,2 % (2023) : × 1,079 = 2,3 ; bornes : 30 % des allocataires (1,7) et 50 % avec la part provisoire 2025, 9,1 % (3,2)",note='Montants des prestations non actualisés (allocataires 2025 : 4,7 M pour les allocations familiales, 5,6 M pour les aides au logement, en baisse ; montants unitaires revalorisés) ; part des titres de moins de 5 ans de 2020 (40 %) non actualisée, alors que les premiers titres ont atteint 384 230 en 2025 (+11,2 %). Verdict « Exige une révision » inchangé.')
M('lisnard','aides5')['claude']['inputs']+=[{'label':'Part des étrangers dans la population','value':'7,6 % (2020), 8,2 % (2023), 9,1 % (2025, provisoire ; rupture de série en 2024)','source':'Insee','url':'https://insee.fr/fr/statistiques/3633212'}]
